// GENERATED by script/spec.ts from cmd.json — do not edit.

use super::*;
use xpute_core::abi::cmd::{cmd, Minor, MINOR_OWN};

#[test]
fn every_number_is_its_major_and_minor() {
    use Command::*;
    let parts = [
        (WORLD_CREATE, Major::WORLD as u32, Minor::CREATE as u32),
        (WORLD_UPDATE, Major::WORLD as u32, Minor::UPDATE as u32),
        (INPUT_UPDATE, Major::INPUT as u32, Minor::UPDATE as u32),
        (INPUT_POINTER, Major::INPUT as u32, InputMinor::POINTER as u32),
        (INPUT_WHEEL, Major::INPUT as u32, InputMinor::WHEEL as u32),
        (INPUT_TRACKING, Major::INPUT as u32, InputMinor::TRACKING as u32),
        (INPUT_VIEW, Major::INPUT as u32, InputMinor::VIEW as u32),
        (INPUT_RESET_DIST, Major::INPUT as u32, InputMinor::RESET_DIST as u32),
        (INPUT_COMPASS_RESET, Major::INPUT as u32, InputMinor::COMPASS_RESET as u32),
        (INPUT_GO_TO, Major::INPUT as u32, InputMinor::GO_TO as u32),
        (SENSOR_UPDATE, Major::SENSOR as u32, Minor::UPDATE as u32),
        (SENSOR_ERROR, Major::SENSOR as u32, SensorMinor::ERROR as u32),
        (SENSOR_ORIENTATION, Major::SENSOR as u32, SensorMinor::ORIENTATION as u32),
        (SENSOR_PERMISSION, Major::SENSOR as u32, SensorMinor::PERMISSION as u32),
        (SENSOR_VISIBILITY, Major::SENSOR as u32, SensorMinor::VISIBILITY as u32),
        (SENSOR_ENABLE, Major::SENSOR as u32, SensorMinor::ENABLE as u32),
        (SENSOR_OPEN, Major::SENSOR as u32, SensorMinor::OPEN as u32),
        (SENSOR_CLOSE, Major::SENSOR as u32, SensorMinor::CLOSE as u32),
        (FETCH_UPDATE, Major::FETCH as u32, Minor::UPDATE as u32),
        (LOAD_UPDATE, Major::LOAD as u32, Minor::UPDATE as u32),
        (LOAD_IMAGE, Major::LOAD as u32, LoadMinor::IMAGE as u32),
        (LOAD_DELETE, Major::LOAD as u32, Minor::DELETE as u32),
        (GPU_CREATE, Major::GPU as u32, Minor::CREATE as u32),
        (GPU_DELETE, Major::GPU as u32, Minor::DELETE as u32),
        (SURFACE_CREATE, Major::SURFACE as u32, Minor::CREATE as u32),
        (SURFACE_UPDATE, Major::SURFACE as u32, Minor::UPDATE as u32),
        (SURFACE_DELETE, Major::SURFACE as u32, Minor::DELETE as u32),
        (SETTING_UPDATE, Major::SETTING as u32, Minor::UPDATE as u32),
        (SETTING_TOGGLE, Major::SETTING as u32, SettingMinor::TOGGLE as u32),
        (CHAT_CREATE, Major::CHAT as u32, Minor::CREATE as u32),
        (PREVIEW_CREATE, Major::PREVIEW as u32, Minor::CREATE as u32),
        (PREVIEW_DELETE, Major::PREVIEW as u32, Minor::DELETE as u32),
        (LEDGER_START, Major::LEDGER as u32, LedgerMinor::START as u32),
        (LEDGER_STOP, Major::LEDGER as u32, LedgerMinor::STOP as u32),
        (LEDGER_LOG, Major::LEDGER as u32, LedgerMinor::LOG as u32),
        (WORLD_SNAPSHOT, Major::WORLD as u32, WorldMinor::SNAPSHOT as u32),
        (SENSOR_CREATE, Major::SENSOR as u32, Minor::CREATE as u32),
        (SENSOR_DELETE, Major::SENSOR as u32, Minor::DELETE as u32),
        (FETCH_CREATE, Major::FETCH as u32, Minor::CREATE as u32),
        (FETCH_DELETE, Major::FETCH as u32, Minor::DELETE as u32),
        (LOAD_CREATE, Major::LOAD as u32, Minor::CREATE as u32),
    ];
    for (c, major, minor) in parts {
        assert_eq!(c as u32, cmd(major, minor), "{c:?}");
        assert_eq!(Command::of(c as u32), Some(c));
    }
    assert_eq!(Command::of(0x0fff), None);
}

/// Nothing computes a minor at run time — every number here is a constant
/// by the time it is on the wire — so what this catches is a subject's own
/// verb written below MINOR_OWN in the JSON, where it would answer to the
/// same number as one of the four every subject has.
#[test]
fn a_subject_s_own_verbs_start_past_the_four_every_subject_has() {
    let own: [(&str, u32); 20] = [
        ("InputMinor::POINTER", InputMinor::POINTER as u32),
        ("InputMinor::WHEEL", InputMinor::WHEEL as u32),
        ("InputMinor::TRACKING", InputMinor::TRACKING as u32),
        ("InputMinor::VIEW", InputMinor::VIEW as u32),
        ("InputMinor::RESET_DIST", InputMinor::RESET_DIST as u32),
        ("InputMinor::COMPASS_RESET", InputMinor::COMPASS_RESET as u32),
        ("InputMinor::GO_TO", InputMinor::GO_TO as u32),
        ("SensorMinor::ERROR", SensorMinor::ERROR as u32),
        ("SensorMinor::ORIENTATION", SensorMinor::ORIENTATION as u32),
        ("SensorMinor::PERMISSION", SensorMinor::PERMISSION as u32),
        ("SensorMinor::VISIBILITY", SensorMinor::VISIBILITY as u32),
        ("SensorMinor::ENABLE", SensorMinor::ENABLE as u32),
        ("SensorMinor::OPEN", SensorMinor::OPEN as u32),
        ("SensorMinor::CLOSE", SensorMinor::CLOSE as u32),
        ("LoadMinor::IMAGE", LoadMinor::IMAGE as u32),
        ("WorldMinor::SNAPSHOT", WorldMinor::SNAPSHOT as u32),
        ("SettingMinor::TOGGLE", SettingMinor::TOGGLE as u32),
        ("LedgerMinor::START", LedgerMinor::START as u32),
        ("LedgerMinor::STOP", LedgerMinor::STOP as u32),
        ("LedgerMinor::LOG", LedgerMinor::LOG as u32),
    ];
    for (name, value) in own {
        assert!(value >= MINOR_OWN, "{name} = {value:#x} is below MINOR_OWN");
    }
}
